        return frame;
    }

    public HistoryEventType getEventType() {
        return eventType;
    }

    public Instant getOccurredAt() {
        return occurredAt;
    }

    public HistorySource getSource() {
        return source;
    }

    public Map<String, FieldChange> getChangedFields() {
        return changedFields;
    }
}

