package com.global.ct.frameinventory.frame;

import java.sql.SQLException;
import java.time.Clock;
import java.time.LocalDateTime;
import java.time.temporal.ChronoUnit;

import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import jakarta.persistence.EntityManager;

@Service
public class FrameService {

    private final FrameRepository repository;
    private final FrameMapper mapper;
    private final Clock clock;
    private final EntityManager entityManager;

    public FrameService(
        FrameRepository repository,
        FrameMapper mapper,
        Clock clock,
        EntityManager entityManager
    ) {
        this.repository = repository;
        this.mapper = mapper;
        this.clock = clock;
        this.entityManager = entityManager;
    }

    @Transactional
    public FrameResponse createFrame(CreateFrameRequest request) {
        if (repository.existsById(request.frameId())) {
            throw new DuplicateFrameException(request.frameId());
        }

        Frame frame = mapper.toNewEntity(request, now());
        try {
            Frame saved = repository.saveAndFlush(frame);
            entityManager.refresh(saved);
            return mapper.toResponse(saved);
        } catch (DataIntegrityViolationException exception) {
            if (isDuplicateKey(exception)) {
                throw new DuplicateFrameException(request.frameId());
            }
            throw exception;
        }
    }

    @Transactional(readOnly = true)
    public FrameResponse getFrame(String frameId) {
        return repository.findById(frameId)
            .map(mapper::toResponse)
            .orElseThrow(() -> new FrameNotFoundException(frameId));
    }

    @Transactional
    public FrameResponse replaceFrame(String frameId, UpdateFrameRequest request) {
        Frame existing = repository.findById(frameId)
            .orElseThrow(() -> new FrameNotFoundException(frameId));
        Frame replacement = mapper.toReplacement(existing, request, now());
        Frame saved = repository.saveAndFlush(replacement);
        entityManager.refresh(saved);
        return mapper.toResponse(saved);
    }

    @Transactional(readOnly = true)
    public FramePageResponse searchFrames(FrameSearchCriteria criteria, Pageable pageable) {
        Page<FrameSummaryResponse> result = repository
            .findAll(FrameSpecifications.matching(criteria), pageable)
            .map(mapper::toSummary);
        return new FramePageResponse(
            result.getContent(), result.getNumber(), result.getSize(),
            result.getTotalElements(), result.getTotalPages()
        );
    }

    private LocalDateTime now() {
        return LocalDateTime.now(clock).truncatedTo(ChronoUnit.MICROS);
    }

    private boolean isDuplicateKey(DataIntegrityViolationException exception) {
        Throwable current = exception;
        while (current != null) {
            if (current instanceof DuplicateKeyException) {
                return true;
            }
            if (current instanceof SQLException sqlException
                && ("23505".equals(sqlException.getSQLState()) || sqlException.getErrorCode() == 1062)) {
                return true;
            }
            current = current.getCause();
        }
        return false;
    }
}

===== FrameSpecifications.java =====
package com.global.ct.frameinventory.frame;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

import org.springframework.data.jpa.domain.Specification;

import jakarta.persistence.criteria.CriteriaBuilder;
import jakarta.persistence.criteria.Expression;
import jakarta.persistence.criteria.Path;
import jakarta.persistence.criteria.Predicate;

final class FrameSpecifications {

    private FrameSpecifications() {
    }

    static Specification<Frame> matching(FrameSearchCriteria criteria) {
        return (root, query, builder) -> {
            List<Predicate> predicates = new ArrayList<>();

            if (criteria.query() != null) {
                String pattern = "%" + escapeLike(criteria.query().toLowerCase(Locale.ROOT)) + "%";
                predicates.add(builder.or(
                    like(builder, root.get("frameId"), pattern),
                    like(builder, root.get("location").get("address"), pattern),
                    like(builder, root.get("location").get("town"), pattern),
                    like(builder, root.get("site").get("station"), pattern),
                    like(builder, root.get("site").get("airport"), pattern),
                    like(builder, root.get("site").get("siteNumber"), pattern)
                ));
            }

            addExact(predicates, builder, root.get("status"), criteria.status());
            addExact(predicates, builder, root.get("mediaType"), criteria.mediaType());
            addExact(predicates, builder, root.get("environment"), criteria.environment());
            addExact(predicates, builder, root.get("format"), criteria.format());
            addExact(predicates, builder, root.get("location").get("region"), criteria.region());

            return builder.and(predicates.toArray(Predicate[]::new));
        };
    }

    private static Predicate like(CriteriaBuilder builder, Path<?> path, String pattern) {
        return builder.like(lower(builder, path), pattern, '\\');
    }

    private static void addExact(
        List<Predicate> predicates,
        CriteriaBuilder builder,
        Path<?> path,
        String value
    ) {
        if (value != null) {
            predicates.add(builder.equal(lower(builder, path), value.toLowerCase(Locale.ROOT)));
        }
    }

    private static Expression<String> lower(CriteriaBuilder builder, Path<?> path) {
        return builder.lower(path.as(String.class));
    }

    private static String escapeLike(String value) {
        return value.replace("\\", "\\\\").replace("%", "\\%").replace("_", "\\_");
    }
}

