    name = "frame_history",
    indexes = @Index(
        name = "idx_frame_history_frame_timestamp",
        columnList = "frame_id, occurred_at"
    )
)
public class FrameHistory {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
