            occurredAt,
            HistorySource.MANUAL,
            changes
        ));
        entityManager.clear();

        List<FrameHistory> history = frameHistoryRepository
            .findByFrameFrameIdOrderByOccurredAtDesc("1234604983");

        assertThat(history).hasSize(1);
